import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

// Shared helpers for the repository checks (CLAUDE.md commands table).

export const ROOT = join(__dirname, '..');

const SKIP_DIRS = new Set(['node_modules', '.git', '.expo', 'build', 'dist', 'coverage', '.gradle', '.kotlin', '.wrangler']);
/** Generated by `expo prebuild`; only at the repo root (the engine module has its own android/). */
const SKIP_AT_ROOT = new Set(['android', 'ios']);

/** Files under `dir` (relative to the repo root) whose names end with one of `exts`. */
export function walk(dir: string, exts: string[]): string[] {
  const out: string[] = [];
  const visit = (abs: string) => {
    let entries: string[];
    try {
      entries = readdirSync(abs);
    } catch {
      return;
    }
    for (const name of entries) {
      const p = join(abs, name);
      if (statSync(p).isDirectory()) {
        if (!SKIP_DIRS.has(name) && !(abs === ROOT && SKIP_AT_ROOT.has(name))) visit(p);
      } else if (exts.some((e) => name.endsWith(e))) out.push(relative(ROOT, p));
    }
  };
  visit(join(ROOT, dir));
  return out.sort();
}

export function read(rel: string): string {
  return readFileSync(join(ROOT, rel), 'utf8');
}

export function readJson<T = unknown>(rel: string): T {
  return JSON.parse(read(rel)) as T;
}

/** Print problems and exit non-zero when there are any. */
export function finish(name: string, problems: string[], warnings: string[] = []) {
  for (const w of warnings) console.warn(`warning: ${w}`);
  if (problems.length) {
    for (const p of problems) console.error(p);
    console.error(`\n${name}: ${problems.length} problem${problems.length === 1 ? '' : 's'}`);
    process.exit(1);
  }
  console.log(`${name}: ok`);
}

/** Every string value in a JSON tree with its dotted path. */
export function strings(node: unknown, path = ''): [string, string][] {
  if (typeof node === 'string') return [[path, node]];
  if (Array.isArray(node)) return node.flatMap((v, i) => strings(v, `${path}[${i}]`));
  if (node && typeof node === 'object') return Object.entries(node).flatMap(([k, v]) => strings(v, path ? `${path}.${k}` : k));
  return [];
}
